public static double calculateAverageBalance(List<Double> closingBalances) {
    if (closingBalances == null || closingBalances.isEmpty()) {
        return 0.0;
    }
    double sum = 0.0;
    int count = 0;
    for (Double balance : closingBalances) {
        if (balance == null) {
            continue;
        }
        sum += balance;
        count++;
    }
    if (count == 0) {
        return 0.0;
    }
    double avg = sum / count;
    return new java.math.BigDecimal(avg).setScale(2, java.math.RoundingMode.HALF_UP).doubleValue();
}

