public static int calculateTimeNeeded(int N) {
    if (N <= 0) {
        throw new IllegalArgumentException("Number of people must be positive");
    }
    if (N < 4) {
        // For 1-3 people, reverse seating order is trivial or not defined
        return 0;
    }
    return 2 * (N - 3);
}

