public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Filter out null strings and find the minimum length
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) {
        return 0;
    }

    // Precompute all substrings of each string for each length
    List<Set<String>> substrSets = new ArrayList<>();
    for (String s : strings) {
        Set<String> set = new HashSet<>();
        for (int len = 1; len <= s.length(); len++) {
            for (int i = 0; i + len <= s.length(); i++) {
                set.add(s.substring(i, i + len));
            }
        }
        substrSets.add(set);
    }

    // Helper to reverse a string
    java.util.function.Function<String, String> reverse = str -> new StringBuilder(str).reverse().toString();

    // Try lengths from largest to smallest
    for (int len = minLen; len >= 1; len--) {
        // Build set of substrings of this length from the first string
        Set<String> firstSet = new HashSet<>();
        String first = strings.get(0);
        for (int i = 0; i + len <= first.length(); i++) {
            firstSet.add(first.substring(i, i + len));
        }

        for (String candidate : firstSet) {
            boolean ok = true;
            String rev = reverse.apply(candidate);
            for (int idx = 1; idx < substrSets.size(); idx++) {
                Set<String> currentSet = substrSets.get(idx);
                if (!currentSet.contains(candidate) && !currentSet.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

