public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
            return "cannot be travelled";
        }
        int sx = start[0], sy = start[1];
        int ex = end[0], ey = end[1];
        if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
            return "cannot be travelled";
        }
        if (sx == ex && sy == ey) {
            return "can be travelled";
        }
        Map<String, List<String>> adj = new HashMap<>();
        if (paths != null) {
            for (int[] p : paths) {
                if (p == null || p.length != 4) continue;
                int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
                if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) continue;
                String a = x1 + "," + y1;
                String b = x2 + "," + y2;
                adj.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
                adj.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
            }
        }
        boolean[][] visited = new boolean[n][n];
        Deque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{sx, sy});
        visited[sx][sy] = true;
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            String key = cur[0] + "," + cur[1];
            List<String> neighbors = adj.get(key);
            if (neighbors == null) continue;
            for (String nb : neighbors) {
                String[] parts = nb.split(",");
                int nx = Integer.parseInt(parts[0]);
                int ny = Integer.parseInt(parts[1]);
                if (!visited[nx][ny]) {
                    if (nx == ex && ny == ey) {
                        return "can be travelled";
                    }
                    visited[nx][ny] = true;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

