public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid date format";
    }
    try {
        java.time.format.DateTimeFormatter inputFormatter = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
        java.time.LocalDate localDate = java.time.LocalDate.parse(date.trim(), inputFormatter);

        java.time.format.DateTimeFormatter monthFormatter = java.time.format.DateTimeFormatter.ofPattern("MMMM");
        java.time.format.DateTimeFormatter dayFormatter = java.time.format.DateTimeFormatter.ofPattern("d");
        java.time.format.DateTimeFormatter yearFormatter = java.time.format.DateTimeFormatter.ofPattern("yyyy");
        java.time.format.DateTimeFormatter weekdayFormatter = java.time.format.DateTimeFormatter.ofPattern("EEEE");

        String month = localDate.format(monthFormatter);
        String day = localDate.format(dayFormatter);
        String year = localDate.format(yearFormatter);
        String weekday = localDate.format(weekdayFormatter);

        return month + " " + day + ", " + year + " is a " + weekday;
    } catch (Exception e) {
        return "Invalid date format";
    }
}

