public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[i] will hold all possible sums of subsets of size i
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using the same element twice
        for (int size = n - 1; size >= 0; size--) {
            if (dp[size].isEmpty()) {
                continue;
            }
            for (int sum : dp[size]) {
                dp[size + 1].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        long targetProduct = (long) k * totalSum;
        if (targetProduct % n != 0) {
            continue;
        }
        int target = (int) (targetProduct / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

