public int minCostClimbingStairs(int[] cost) {
    try {
        if (cost == null || cost.length == 0) {
            return 0;
        }
        int n = cost.length;
        if (n == 1) {
            return 0;
        }
        int[] dp = new int[n + 1];
        dp[0] = 0;
        dp[1] = 0;
        for (int i = 2; i <= n; i++) {
            int stepCost = cost[i - 1];
            dp[i] = stepCost + Math.min(dp[i - 1], dp[i - 2]);
        }
        return dp[n];
    } catch (Exception e) {
        // In case of unexpected errors, return 0 as a safe fallback
        return 0;
    }
}

