public boolean hasAllCodes(String s, int k) {
    if (s == null) return false;
    int n = s.length();
    if (k <= 0) return true; // empty string is always a substring
    long totalLong = 1L << k;
    if (totalLong > Integer.MAX_VALUE) return false; // too many codes to handle
    int total = (int) totalLong;
    if (n < total) return false;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen[code] = true;
        }
    }
    for (boolean present : seen) {
        if (!present) return false;
    }
    return true;
}

