public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                // Need an opening bracket before this ')'
                insertions++;
                balance = 0;
            }
        } else {
            // Invalid character, ignore or throw exception
            // For safety, treat as no effect
        }
    }
    // Remaining unmatched '(' need closing brackets
    insertions += balance;
    return insertions;
}

