public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int[] max = new int[1];
    class Solver {
        void dfs(int index, java.util.Set<String> used) {
            if (index == n) {
                max[0] = Math.max(max[0], used.size());
                return;
            }
            for (int end = index + 1; end <= n; end++) {
                String sub = s.substring(index, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    dfs(end, used);
                    used.remove(sub);
                }
            }
        }
    }
    new Solver().dfs(0, new java.util.HashSet<>());
    return max[0];
}

